	/**
	 * 顶部菜单环境
	 *
	 * @public
	 */
	enum ESYS_HeaderMenuEnvironment {
		/** 主页 */ HOME = 'home',
		/** 空白页 */ BLANK = 'blank',
		/** 原理图 */ SCHEMATIC = 'sch',
		/** 符号（包括 CBB 符号） */ SYMBOL = 'symbol',
		/** PCB */ PCB = 'pcb',
		/** 封装 */ FOOTPRINT = 'footprint',
		/** PCB 预览（包括 2D、3D 预览） */ PCB_VIEW = 'pcbView',
		/** 面板 */ PANEL = 'panel',
		/** 面板库 */ PANEL_LIBRARY = 'panelLibrary',
		/** 面板预览 */ PANEL_VIEW = 'panelView',
		/** 仿真原理图：Ngspice */ SIMULATION_SCHEMATIC_NGSPICE = 'simulationSchematicNgspice',
		/** 仿真原理图：SimulIDE */ SIMULATION_SCHEMATIC_SIMULIDE = 'simulationSchematicSimulIDE',
	}
	/**
	 * 系统 / 顶部菜单类
	 *
	 * @public
	 */
	class SYS_HeaderMenu {
		/** 扩展 UUID */
		private extensionUuid?: string;
		/**
		 * @internal
		 * @param extensionUuid - 扩展 UUID
		 */
		public constructor(extensionUuid?: string);
		/**
		 * 导入顶部菜单数据
		 *
		 * @public
		 * @param headerMenus - 顶部菜单数据
		 * @example
		 * ```javascript
		 * // 1. 组装菜单数据：环境键 → 一级菜单数组（title / id / menuItems）
		 * const headerMenus = {
		 *   blank: [
		 *     {
		 *       id: '嘉立创示例_菜单',
		 *       title: '嘉立创示例',
		 *       menuItems: [{ id: '嘉立创示例_子项', title: '打开示例面板' }],
		 *     },
		 *   ],
		 * };
		 *
		 * // 2. 导入顶部菜单数据（blank 环境的顶部菜单被替换为上述内容）
		 * await eda.sys_HeaderMenu.insertHeaderMenus(headerMenus);
		 * console.log('已导入 blank 环境的顶部菜单数据');
		 *
		 * // 3. 还原：移除导入的数据，恢复系统默认菜单
		 * eda.sys_HeaderMenu.removeHeaderMenus();
		 * console.log('已还原系统默认菜单');
		 * ```
		 */
		public insertHeaderMenus(headerMenus: ISYS_HeaderMenus): Promise<void>;
		/**
		 * 移除顶部菜单数据
		 *
		 * @public
		 * @example
		 * ```javascript
		 * // 1. 先导入一份菜单数据，让移除操作有实际对象
		 * await eda.sys_HeaderMenu.insertHeaderMenus({
		 *   blank: [{ id: '嘉立创示例_菜单', title: '嘉立创示例', menuItems: [{ id: '嘉立创示例_子项', title: '示例子项' }] }],
		 * });
		 * console.log('已导入菜单数据');
		 *
		 * // 2. 移除全部已导入的顶部菜单数据（同步方法，无需 await）
		 * eda.sys_HeaderMenu.removeHeaderMenus();
		 * console.log('已移除导入的顶部菜单数据');
		 * ```
		 */
		public removeHeaderMenus(): void;
		/**
		 * 替换顶部菜单数据
		 *
		 * @public
		 * @remarks 本接口相当于同时执行了 {@link SYS_HeaderMenu.removeHeaderMenus | 移除} 和 {@link SYS_HeaderMenu.insertHeaderMenus | 导入} 操作
		 * @param headerMenus - 顶部菜单数据
		 * @example
		 * ```javascript
		 * // 1. 先导入一版菜单数据作为被替换对象（blank 空白页环境）
		 * await eda.sys_HeaderMenu.insertHeaderMenus({
		 *   blank: [{ id: '嘉立创示例_菜单A', title: '菜单 A', menuItems: [{ id: '嘉立创示例_子A', title: '子项 A' }] }],
		 * });
		 * console.log('已导入第一版菜单');
		 *
		 * // 2. 整体替换为第二版菜单数据
		 * await eda.sys_HeaderMenu.replaceHeaderMenus({
		 *   blank: [{ id: '嘉立创示例_菜单B', title: '菜单 B', menuItems: [{ id: '嘉立创示例_子B', title: '子项 B' }] }],
		 * });
		 * console.log('已替换为第二版菜单');
		 *
		 * // 3. 还原系统默认菜单
		 * eda.sys_HeaderMenu.removeHeaderMenus();
		 * console.log('已还原系统默认菜单');
		 * ```
		 */
		public replaceHeaderMenus(headerMenus: ISYS_HeaderMenus): Promise<void>;
		/**
		 * 移除系统顶部菜单项
		 *
		 * @beta
		 * @remarks
		 * 一旦菜单被移除，需要重启嘉立创 EDA 软件才可以恢复
		 *
		 * 本接口无法移除 {@link SYS_HeaderMenu.insertSystemHeaderMenus | 导入系统顶部菜单} 接口导入的系统顶部菜单项
		 *
		 * 当 `id` 数组仅包含一个元素时，将移除对应的一级菜单；当 `id` 数组包含多个元素时，将按照数组顺序按层级匹配菜单项，并移除数组最后一位对应的子菜单项
		 *
		 * 本接口无法移除 **高级** 菜单本身及其下的任何子菜单
		 *
		 * 注意 1：本接口需要使用者启用扩展的外部交互权限，如若未启用将始终 `throw Error`
		 *
		 * 注意 2：本接口 **移除一级菜单** 为私有化部署版本专用功能，如若在其它版本调用将始终 `throw Error`
		 *
		 * 非公开接口使用提醒：本接口按原样提供，不提供参数的额外文档，参数可能在任何版本出现破坏性更改并不另行通知
		 * @param env - 环境
		 * @param id - 菜单项 ID 树，将会按照数组顺序按层级匹配菜单项，并移除数组最后一位对应的菜单项；仅传递一个元素时移除对应的一级菜单
		 * @param props - 其它参数，是否移除菜单项之前、之后的分隔线（仅在移除子菜单项时生效）
		 * @returns 移除操作是否成功，菜单已移除但分隔线未找到也会返回 `true` 的结果
		 * @example
		 * ```javascript
		 * // 1. 先插入一个待移除的子菜单项（id 树：[一级菜单 ID, 新项 ID]）
		 * const menuId = await eda.sys_HeaderMenu.insertSystemHeaderMenuItem('pcb', ['Tools', '嘉立创示例_待移除项'], {
		 *   title: '嘉立创示例 待移除项',
		 * });
		 * console.log('待移除的菜单 ID：', menuId);
		 *
		 * // 2. 移除该菜单项（id 树：[一级菜单 ID, insert 返回的重写 ID]）
		 * const removed = await eda.sys_HeaderMenu.removeSystemHeaderMenuItem(['Tools', menuId]);
		 * console.log('移除结果：', removed);
		 * ```
		 */
		public removeSystemHeaderMenuItem(id: Array<string>, props?: {
			/** 是否移除前面的分隔线 */ removeTheBeforeDivider?: boolean;
			/** 是否移除后面的分隔线 */ removeTheAfterDivider?: boolean;
		}): Promise<boolean>;
		/**
		 * 在指定位置插入系统顶部菜单项
		 *
		 * @beta
		 * @remarks
		 * 本接口需要在系统已有的系统一级菜单下新增子菜单，无法新增和修改一级菜单，`id` 数组请至少传递 `2` 个值
		 *
		 * 本接口将会强制新建的系统顶部菜单的 ID 包含扩展 UUID，例如输入的 `id = 'example'`，将会被自动重写为 `e143d88179874e7f851cc890cd22fc71|example`，后续如需移除该菜单，请输入重写后的名称
		 *
		 * 本接口不能在 **高级** 菜单下新增任何子菜单
		 *
		 * 本接口新增的子菜单将默认排列在原菜单的结尾，除非指定了 `props.insertBefore` 参数
		 *
		 * 注意：本接口需要使用者启用扩展的外部交互权限，如若未启用将始终 `throw Error`
		 *
		 * 非公开接口使用提醒：本接口按原样提供，不提供参数的额外文档，参数可能在任何版本出现破坏性更改并不另行通知
		 * @param env - 环境
		 * @param id - 菜单项 ID 树，将会按照数组顺序按层级匹配菜单项，并将数组最后一位作为插入的菜单项的 ID
		 * @param props - 其它参数
		 * @returns 顶部菜单项的 ID，分隔线是否插入并不会影响操作结果的返回值，不包含 menuItems 中的子项的 ID
		 * @example
		 * ```javascript
		 * // 1. 在 PCB 环境的 工具（Tools）菜单下插入子菜单项，并带上两个三级菜单项
		 * const menuId = await eda.sys_HeaderMenu.insertSystemHeaderMenuItem('pcb', ['Tools', '嘉立创示例_扩展工具'], {
		 *   title: '嘉立创示例 扩展工具',
		 *   menuItems: [
		 *     { id: '嘉立创示例_打开面板', title: '打开扩展面板' },
		 *     { id: '嘉立创示例_扩展设置', title: '扩展设置' },
		 *   ],
		 * });
		 *
		 * // 2. 输出重写后的菜单 ID（真实扩展中通过 registerFn 指定点击回调）
		 * console.log('插入的菜单 ID：', menuId);
		 *
		 * // 3. 移除刚插入的菜单项还原菜单栏（同一 ID 重复插入会返回 undefined，
		 * //    自建自删保证案例可重复运行）
		 * const removed = await eda.sys_HeaderMenu.removeSystemHeaderMenuItem(['Tools', menuId]);
		 * console.log('移除结果：', removed);
		 * ```
		 */
		public insertSystemHeaderMenuItem(env: ESYS_HeaderMenuEnvironment, id: Array<string>, props: {
			/** 菜单项的标题 */ title: string;
			/** 注册方法名称 */ registerFn?: string;
			/** 菜单项图标，SVG 数据 */ icon?: string;
			/** 局部快捷键 */ shortcutKey?: TSYS_ShortcutKeys;
			/** 子菜单项 */ menuItems?: Array<ISYS_HeaderMenuSub1MenuItem | ISYS_HeaderMenuSub2MenuItem | null>;
			/** 是否在前面插入分隔线 */ insertDividerBefore?: boolean;
			/** 是否在后面插入分隔线  */ insertDividerAfter?: boolean;
			/** 在指定 ID 的菜单项的前面插入当前菜单项 */ insertBefore?: string;
			/** 在插入时如若指定的菜单项前面存在分隔线，是否跨过该分隔线（即和 insertBefore 指定 ID 的菜单项之间是否可能存在分隔线，这和 insertDividerAfter 并不冲突，因为 insertDividerAfter 在菜单项插入完成后添加） */ crossDividerWhenInsert?: boolean;
		}): Promise<string | undefined>;
		/**
		 * 导入系统顶部菜单 **暂不开发**
		 *
		 * @internal
		 * @remarks
		 * 系统顶部菜单一旦新增无法有效删除，需要重启嘉立创 EDA 软件才可以恢复
		 *
		 * 本接口需要在系统已有的系统一级菜单下新增子菜单，无法新增和修改一级菜单
		 *
		 * 本接口不能在 **高级** 菜单下新增任何子菜单
		 *
		 * 本接口新增的子菜单将默认排列在原菜单的结尾
		 *
		 * 注意：本接口需要使用者启用扩展的外部交互权限，如若未启用将始终 `throw Error`
		 *
		 * 非公开接口使用提醒：本接口按原样提供，不提供参数的额外文档，参数可能在任何版本出现破坏性更改并不另行通知
		 * @param headerMenus - 顶部菜单数据
		 * @example
		 * headerMenus:
		 *
		 * ```typescript
		 * const headerMenus = {
		 * 	sch: [
		 * 		null,
		 * 		{
		 * 			id: 'eda|help',
		 * 			title: '扩展开发指南...',
		 * 			registerFn: 'aboutExtension',
		 * 		},
		 * 	],
		 * };
		 * ```
		 */
		public insertSystemHeaderMenus(headerMenus: ISYS_HeaderMenus): void;
	}
	/**
	 * lc-build 生成的 API jsonSchema（d.ts 的 JSON 形态）
	 *
	 * @public
	 * @remarks 结构：`$defs.{类型名}.{...jsonSchema}`，类的方法位于 `properties` 下
	 */
	interface ISYS_HelpData {
		/** JSON Schema 版本 */
		$schema?: string;
		/** 类型定义表：类型名 -> 类型 schema */
		$defs?: Record<string, any>;
	}
	/**
	 * 由 help 查询返回的类摘要
	 *
	 * @public
	 */
	interface ISYS_HelpClassSummary {
		/** 类标题 */
		title?: string;
		/** 类说明 */
		remarks?: string;
		/** 类废弃说明 */
		deprecated?: string;
		/**
		 * 方法列表
		 *
		 * @remarks
		 * 类场景为方法条目 `{ name, comment }`；external 场景为接口名 `string`（无注释结构）
		 */
		methods: Array<string | { name: string; comment?: string }>;
		/** 各接口标题（external 场景，键为接口名） */
		titles?: Record<string, string | undefined>;
	}
	/**
	 * Help 查询返回的方法详情
	 *
	 * @public
	 */
	interface ISYS_HelpMethodDetail {
		/** 方法标题 */
		title?: string;
		/** 方法说明 */
		remarks?: string;
		/** 入参列表 */
		params?: Array<{
			name: string;
			type?: string;
			description?: string;
			required?: boolean;
			/** 参数废弃说明 */ deprecated?: string;
		}>;
		/** 返回值 */
		returns?: { type?: string; description?: string };
		/** 方法废弃说明 */
		deprecated?: string;
		/** 方法是否异步（返回 Promise，调用时需 `await`） */
		isAsync?: boolean;
		/** 使用示例 */
		example?: string;
	}
	/**
	 * Help 渐进式披露类
	 *
	 * @public
	 * @remarks
	 * 用于渐进式披露外部 API（`eda`）、lc-protocol 格式类型（`format`）与扩展注入接口（`external`）的信息；
	 *
	 * AI 可先获取 API 总览（各命名空间下全部类型条目 `{ name, comment }`），
	 * 再按需查询单个命名空间、单个类 / 类型、单个方法的详细用法（入参、出参、返回值），
	 * 无需翻阅大量外部文档
	 */
	class SYS_Help {
		/**
		 * 查询 Help 信息（渐进式）
		 *
		 * @public
		 * @param namespace - 命名空间：`'eda'`（静态外部 API）、`'format'`（lc-protocol 格式类型）或 `'external'`（扩展注入接口），缺省返回总览
		 * @param className - 类名 / 类型名 / 命名空间下的分组名（external 场景为注册时的 namespace）
		 * @param methodName - 方法名 / 接口名
		 * @returns 渐进式查询结果：
		 *
		 * - 无参：返回总览 `{ eda: [{ name, comment } 全部类型条目], external: { namespace: { apiName: 标题 } } }`；
		 * - 仅 `namespace`（`'eda'` / `'format'`）：返回该命名空间下全部类型条目 `[{ name, comment }]`（类 / 枚举 / 接口 / 类型）；
		 * - `namespace` + `className`：类返回 `{ title, methods: [{ name, comment }] }` 方法摘要，
		 *   枚举 / 接口 / 类型返回类型详情（`{ name, comment, values }` 枚举值列表或 `{ name, comment, fields }` 字段列表）；
		 * - 三个参数齐全（`'eda'` 场景）：返回单方法的完整详情（入参、出参、返回值）；
		 * - `'format'` 场景：仅 `namespace` 返回类型条目列表，`namespace` + `className` 返回该类型的详情（无 `methodName` 层级）
		 * @example
		 * ```javascript
		 * // 1. 总览
		 * const overview = await eda.sys_Help.help();
		 *
		 * // 2. 查看 eda 下 lib_Device 类的方法
		 * const deviceMethods = await eda.sys_Help.help('eda', 'lib_Device');
		 *
		 * // 3. 查看 create 方法的完整用法
		 * const createDoc = await eda.sys_Help.help('eda', 'lib_Device', 'create');
		 *
		 * // 4. 查看外部注入接口
		 * const externalInfo = await eda.sys_Help.help('external', 'component', 'placeComponent');
		 * ```
		 */
		public help(namespace?: string, className?: string, methodName?: string): Promise<ISYS_HelpData | Record<string, any> | ISYS_HelpClassSummary | ISYS_HelpMethodDetail>;
	}
	/**
	 * 语言数据键值对
	 *
	 * @public
	 * @remarks 单一语言的数据
	 */
	type TSYS_LanguageKeyValuePairs = Record<string, string>;
	/**
	 * 多语言数据
	 *
	 * @public
	 * @remarks 包含同一命名空间下的多种语言的数据
	 */
	interface ISYS_MultilingualLanguagesData {
		[language: string]: TSYS_LanguageKeyValuePairs;
	}
	/**
	 * 系统 / 多语言类
	 *
	 * @public
	 * @remarks 使用多语言系统展示多语言文本
	 */
	class SYS_I18n {
		/** 扩展 UUID */
		private extensionUuid?: string;
		/**
		 * @internal
		 * @param extensionUuid - 扩展 UUID
		 */
		public constructor(extensionUuid?: string);
		/**
		 * 输出语言文本
		 *
		 * @public
		 * @remarks
		 * 可以使用 `${1}` 格式的占位符表示参数；
		 *
		 * 语言优先级：当前显示语言 \> 系统默认语言 \> 数据集中第一个搜索到的包含该文本标签的语言 \> 文本标签(tag)
		 * @param tag - 文本标签，对应多语言文件键值对中的键
		 * @param namespace - 文本命名空间，在扩展运行环境内默认为扩展的 UUID，否则为系统默认命名空间
		 * @param language - 语言，`undefined` 为 EDA 当前的显示语言
		 * @param args - 语言文本中替换占位符的参数
		 * @returns 语言文本
		 * @example
		 * ```javascript
		 * // 1. 先导入一份多语言数据作为取文本的数据源
		 * eda.sys_I18n.importMultilingualNamespace('嘉立创示例_取文本', {
		 *   'zh-Hans': { '示例_问候': '你好，${1}！今天是${2}' },
		 *   en: { '示例_问候': 'Hello, ${1}! Today is ${2}' },
		 * });
		 *
		 * // 2. 指定语言取文案，占位符按参数顺序替换
		 * const greeting = eda.sys_I18n.text('示例_问候', '嘉立创示例_取文本', 'en', 'Tom', 'Monday');
		 *
		 * // 3. 不传语言则用 EDA 当前显示语言；缺参的占位符原样保留
		 * const current = await eda.sys_I18n.getCurrentLanguage();
		 * const localized = eda.sys_I18n.text('示例_问候', '嘉立创示例_取文本', undefined, '嘉立创');
		 *
		 * // 4. 标签不存在时回退为标签本身
		 * const missing = eda.sys_I18n.text('示例_不存在的标签', '嘉立创示例_取文本');
		 *
		 * console.log('当前语言：', current);
		 * console.log('英文文案：', greeting);
		 * console.log('当前语言文案：', localized);
		 * console.log('缺失标签回退：', missing);
		 * ```
		 */
		public text(tag: string, namespace?: string, language?: string, ...args: Array<any>): string;
		/**
		 * 获取当前语言环境
		 *
		 * @public
		 * @remarks 能够获取到的语言受 EDA 当前支持语言限制，其它 API 支持的语言需要显式指定 `language` 参数才能使用
		 * @returns 语言
		 * @example
		 * ```javascript
		 * // 1. 获取当前显示语言
		 * const current = await eda.sys_I18n.getCurrentLanguage();
		 *
		 * // 2. 判断当前是否中文环境
		 * console.log('当前语言：', current);
		 * console.log('是否中文环境：', current.startsWith('zh'));
		 * ```
		 */
		public getCurrentLanguage(): Promise<string>;
		/**
		 * 查询所有支持的语言
		 *
		 * @public
		 * @returns 所有支持的语言列表
		 * @example
		 * ```javascript
		 * // 1. 获取所有支持的语言代码
		 * const languages = eda.sys_I18n.getAllSupportedLanguages();
		 *
		 * // 2. 输出语言总数，并确认常用语言在列表中
		 * console.log('支持的语言数量：', languages.length);
		 * console.log(
		 *   '常用语言受支持：',
		 *   ['zh-Hans', 'zh-Hant', 'en', 'ja'].every((lang) => languages.includes(lang)),
		 * );
		 * ```
		 */
		public getAllSupportedLanguages(): Array<string>;
		/**
		 * 检查语言是否受支持
		 *
		 * @public
		 * @param language - 语言
		 * @returns 是否受支持
		 * @example
		 * ```javascript
		 * // 1. 检查受支持的语言代码
		 * console.log('en 是否受支持：', eda.sys_I18n.isLanguageSupported('en'));
		 * console.log('zh-Hans 是否受支持：', eda.sys_I18n.isLanguageSupported('zh-Hans'));
		 *
		 * // 2. 检查不受支持的写法（zh-CN 不是 EDA 的语言代码风格）
		 * console.log('zh-CN 是否受支持：', eda.sys_I18n.isLanguageSupported('zh-CN'));
		 * ```
		 */
		public isLanguageSupported(language: string): boolean;
		/**
		 * 导入多语言
		 *
		 * @public
		 * @remarks 注意：本接口仅扩展有效，在独立脚本环境内调用将始终 `throw Error`
		 * @param language - 语言
		 * @param source - 欲导入的多语言数据对象
		 * @returns 导入是否成功
		 * @example
		 * ```javascript
		 * // 1. 向默认命名空间导入简体中文文案（${1} 是占位符，取文案时传实际参数）
		 * const imported = eda.sys_I18n.importMultilingual('zh-Hans', {
		 *   '嘉立创示例_问候': '你好，${1}！欢迎回来',
		 * });
		 *
		 * // 2. 用 text() 按标签取回文案，占位符由参数替换
		 * const message = eda.sys_I18n.text('嘉立创示例_问候', undefined, 'zh-Hans', '工程师');
		 *
		 * console.log('导入结果：', imported);
		 * console.log('取回文案：', message);
		 * ```
		 */
		public importMultilingual(language: string, source: TSYS_LanguageKeyValuePairs): boolean;
		/**
		 * 导入多语言：指定命名空间和语言
		 *
		 * @public
		 * @param namespace - 命名空间
		 * @param language - 语言
		 * @param source - 欲导入的多语言数据对象
		 * @returns 导入是否成功
		 * @example
		 * ```javascript
		 * // 1. 向命名空间导入繁体中文文案
		 * const imported = eda.sys_I18n.importMultilingualLanguage('嘉立创示例_语言包', 'zh-Hant', {
		 *   '示例_问候': '妳好，${1}',
		 * });
		 *
		 * // 2. 用 text() 指定命名空间和语言取回文案
		 * const message = eda.sys_I18n.text('示例_问候', '嘉立创示例_语言包', 'zh-Hant', '用戶');
		 *
		 * console.log('导入结果：', imported);
		 * console.log('繁体文案：', message);
		 * ```
		 */
		public importMultilingualLanguage(namespace: string, language: string, source: TSYS_LanguageKeyValuePairs): boolean;
		/**
		 * 导入多语言：指定命名空间
		 *
		 * @public
		 * @param namespace - 命名空间
		 * @param source - 欲导入的多语言数据对象
		 * @returns 导入是否成功
		 * @example
		 * ```javascript
		 * // 1. 组装多语言数据：语言代码 → 键值对
		 * const languagesData = {
		 *   'zh-Hans': { '示例_问候': '你好，${1}' },
		 *   en: { '示例_问候': 'Hello, ${1}' },
		 * };
		 *
		 * // 2. 一次性导入整个命名空间
		 * const imported = eda.sys_I18n.importMultilingualNamespace('嘉立创示例_多语言', languagesData);
		 *
		 * // 3. 同一标签分别取中英文文案
		 * const zhText = eda.sys_I18n.text('示例_问候', '嘉立创示例_多语言', 'zh-Hans', '工程师');
		 * const enText = eda.sys_I18n.text('示例_问候', '嘉立创示例_多语言', 'en', 'engineer');
		 *
		 * console.log('导入结果：', imported);
		 * console.log('中文文案：', zhText);
		 * console.log('英文文案：', enText);
		 * ```
		 */
		public importMultilingualNamespace(namespace: string, source: ISYS_MultilingualLanguagesData): boolean;
		/**
		 * 新增语言切换事件监听
		 *
		 * @public
		 * @param id - 事件 ID，用以防止重复注册事件
		 * @param callFn - 事件触发时的回调函数
		 * @example
		 * ```javascript
		 * // 1. 注册语言切换监听（回调要等用户真实切换语言时才会触发）
		 * eda.sys_I18n.addLanguageChangedEventListener(
		 *   '嘉立创示例_语言监听',
		 *   (newLanguage, lastLanguage) => {
		 *     console.log('语言已切换：', lastLanguage, '→', newLanguage);
		 *   },
		 *   false,
		 * );
		 *
		 * // 2. 确认监听已注册
		 * console.log('监听已注册：', eda.sys_I18n.isEventListenerAlreadyExist('嘉立创示例_语言监听'));
		 *
		 * // 3. 移除监听，恢复原状（保证案例可重复运行）
		 * console.log('已移除监听：', eda.sys_I18n.removeEventListener('嘉立创示例_语言监听'));
		 * ```
		 */
		public addLanguageChangedEventListener(id: string, callFn: (newLanguage: string, lastLanguage: string) => void | Promise<void>, onlyOnce: boolean): void;
		/**
		 * 移除事件监听
		 *
		 * @public
		 * @param id - 事件 ID
		 * @returns 是否移除指定事件监听
		 * @example
		 * ```javascript
		 * // 1. 先注册一个测试监听作为移除对象
		 * eda.sys_I18n.addLanguageChangedEventListener('嘉立创示例_移除监听', () => {}, false);
		 *
		 * // 2. 第一次移除：ID 存在，返回 true
		 * console.log('第一次移除成功：', eda.sys_I18n.removeEventListener('嘉立创示例_移除监听'));
		 *
		 * // 3. 第二次移除：ID 已不存在，返回 false
		 * console.log('第二次移除成功：', eda.sys_I18n.removeEventListener('嘉立创示例_移除监听'));
		 * ```
		 */
		public removeEventListener(id: string): boolean;
		/**
		 * 查询事件监听是否存在
		 *
		 * @public
		 * @param id - 事件 ID
		 * @returns 事件监听是否存在
		 * @example
		 * ```javascript
		 * // 1. 注册一个测试监听作为查询对象
		 * eda.sys_I18n.addLanguageChangedEventListener('嘉立创示例_查询监听', () => {}, false);
		 *
		 * // 2. 查询已注册与未注册的 ID
		 * console.log('已注册的 ID 存在：', eda.sys_I18n.isEventListenerAlreadyExist('嘉立创示例_查询监听'));
		 * console.log('未注册的 ID 存在：', eda.sys_I18n.isEventListenerAlreadyExist('嘉立创示例_未注册'));
		 *
		 * // 3. 清理测试监听
		 * eda.sys_I18n.removeEventListener('嘉立创示例_查询监听');
		 * console.log('已清理测试监听');
		 * ```
		 */
		public isEventListenerAlreadyExist(id: string): boolean;
	}
