	/**
	 * 扩展注入的上层接口注册条目
	 *
	 * @public
	 * @remarks 存储在 gVars.extensionRegisteredExternalApis 与 gVars.extensionExternalApiIndex 中
	 */
	interface ISYS_ExternalApiRegistration {
		/** 注册该接口的扩展 UUID */
		extensionUuid: string;
		/** 注册顺序，越小越优先（最早注册优先） */
		priority: number;
		/** 实际调用函数 */
		callFn: (...args: any[]) => any | Promise<any>;
		/** Help 元数据（可选） */
		help?: ISYS_ExternalApiHelp;
	}
	/**
	 * external API 扁平索引（按命名空间分组）
	 *
	 * @public
	 * @remarks 键结构：namespace -> apiName -> 注册者列表（按 priority 升序）
	 * 便于调用时 O(1) 查找并按优先级取第一个（最早注册优先）
	 */
	interface ISYS_ExtensionExternalApiIndex {
		[namespace: string]: { [apiName: string]: Array<ISYS_ExternalApiRegistration> };
	}
	/**
	 * 扩展注入的上层接口注册表（按扩展分组）
	 *
	 * @public
	 * @remarks 键结构：extensionUuid -> namespace -> apiName -> 注册条目
	 * 便于按扩展卸载时整组清理
	 */
	interface ISYS_ExtensionRegisteredExternalApis {
		[extensionUuid: string]: { [namespace: string]: { [apiName: string]: ISYS_ExternalApiRegistration } };
	}
